<?php
namespace App\services;
use App\config\Database;
use App\providers\HttpClient;
use App\utils\Logger;
use App\utils\Request;
use RuntimeException;
final class MercadoPagoService {
    private function headers():array{$token=(string)env('MERCADOPAGO_ACCESS_TOKEN','');if($token==='')throw new RuntimeException('Mercado Pago não configurado. Informe MERCADOPAGO_ACCESS_TOKEN.');return ['Authorization: Bearer '.$token];}
    public function createSubscription(array $user,int $planId):array{$pdo=Database::get();$s=$pdo->prepare('SELECT * FROM plans WHERE id=? AND active=1');$s->execute([$planId]);$plan=$s->fetch();if(!$plan)throw new RuntimeException('Plano inválido.');if((float)$plan['price']<=0)throw new RuntimeException('O plano gratuito não precisa de checkout.');$existing=$pdo->prepare('SELECT * FROM subscriptions WHERE user_id=?');$existing->execute([$user['id']]);$old=$existing->fetch();if($old&&$old['provider_subscription_id']&&in_array($old['status'],['active','pending','paused'],true)){try{$this->updateProviderSubscription($old['provider_subscription_id'],['status'=>'cancelled']);}catch(\Throwable $e){Logger::write('payments','cancel_previous_failed',['subscription_id'=>$old['id'],'error'=>$e->getMessage()]);}}
        $ref='sub_'.$user['id'].'_'.$planId.'_'.bin2hex(random_bytes(6));$body=['reason'=>env('APP_NAME','EquipeAI').' - '.$plan['name'],'external_reference'=>$ref,'payer_email'=>$user['email'],'auto_recurring'=>['frequency'=>(int)$plan['billing_frequency'],'frequency_type'=>$plan['billing_frequency_type'],'transaction_amount'=>(float)$plan['price'],'currency_id'=>'BRL'],'back_url'=>rtrim((string)env('FRONTEND_URL',env('APP_URL','')),'/').'/app/assinatura?retorno=mercadopago','status'=>'pending'];$d=HttpClient::post('https://api.mercadopago.com/preapproval',$this->headers(),$body);$providerId=$d['id']??null;$init=$d['init_point']??null;if(!$providerId||!$init)throw new RuntimeException('Mercado Pago não retornou o checkout da assinatura.');$pdo->prepare("INSERT INTO subscriptions(user_id,plan_id,provider,provider_subscription_id,external_reference,status,created_at,updated_at) VALUES(?,?,'mercadopago',?,?,'pending',NOW(),NOW()) ON DUPLICATE KEY UPDATE plan_id=VALUES(plan_id),provider='mercadopago',provider_subscription_id=VALUES(provider_subscription_id),external_reference=VALUES(external_reference),status='pending',cancelled_at=NULL,updated_at=NOW()")->execute([$user['id'],$planId,$providerId,$ref]);Logger::write('payments','subscription_checkout_created',['user_id'=>$user['id'],'plan_id'=>$planId,'provider_subscription_id'=>$providerId]);return ['checkout_url'=>$init,'subscription_id'=>$providerId];}
    public function cancel(array $user):array{$pdo=Database::get();$s=$pdo->prepare('SELECT * FROM subscriptions WHERE user_id=? LIMIT 1');$s->execute([$user['id']]);$sub=$s->fetch();if(!$sub)throw new RuntimeException('Assinatura não encontrada.');if($sub['provider']==='mercadopago'&&$sub['provider_subscription_id'])$this->updateProviderSubscription($sub['provider_subscription_id'],['status'=>'cancelled']);$pdo->prepare("UPDATE subscriptions SET status='cancelled',cancelled_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$sub['id']]);return ['message'=>'Assinatura cancelada. O saldo atual de créditos permanece disponível até ser utilizado.'];}
    private function updateProviderSubscription(string $id,array $body):array{return HttpClient::put('https://api.mercadopago.com/preapproval/'.rawurlencode($id),$this->headers(),$body);}
    public function webhook(array $payload,array $query):void{$this->validateSignature($payload,$query);$type=(string)($payload['type']??$query['type']??$query['topic']??'unknown');$resource=(string)($payload['data']['id']??$query['data_id']??$query['id']??'');$eventKey=hash('sha256','mercadopago|'.($payload['id']??'').'|'.$type.'|'.$resource.'|'.($payload['action']??''));$pdo=Database::get();try{$pdo->prepare("INSERT INTO webhook_events(provider,event_key,event_type,resource_id,payload,status,created_at) VALUES('mercadopago',?,?,?,?, 'received',NOW())")->execute([$eventKey,$type,$resource,json_encode($payload,JSON_UNESCAPED_UNICODE)]);}catch(\PDOException $e){if((string)$e->getCode()==='23000')return;throw $e;}
        try{if($resource===''){$this->markEvent($eventKey,'ignored');return;}if($type==='subscription_preapproval')$this->syncSubscription($resource);elseif($type==='payment')$this->syncPayment($resource);elseif($type==='subscription_authorized_payment')$this->syncAuthorizedPayment($resource);else{$this->markEvent($eventKey,'ignored');return;}$this->markEvent($eventKey,'processed');}catch(\Throwable $e){$this->markEvent($eventKey,'error',$e->getMessage());throw $e;}}
    private function validateSignature(array $payload,array $query):void{$secret=(string)env('MERCADOPAGO_WEBHOOK_SECRET','');if($secret==='')return;$sig=$_SERVER['HTTP_X_SIGNATURE']??'';$requestId=$_SERVER['HTTP_X_REQUEST_ID']??'';$parts=[];foreach(explode(',',$sig) as $p){[$k,$v]=array_pad(explode('=',trim($p),2),2,'');if($k!=='')$parts[$k]=$v;}$ts=$parts['ts']??'';$v1=$parts['v1']??'';$id=(string)($payload['data']['id']??$query['data_id']??$query['id']??'');if($id!==''&&ctype_alnum(str_replace('-','',$id)))$id=strtolower($id);$manifest=($id!==''?'id:'.$id.';':'').'request-id:'.$requestId.';ts:'.$ts.';';$expected=hash_hmac('sha256',$manifest,$secret);if($ts===''||$v1===''||!hash_equals($expected,$v1)){Logger::write('security','invalid_mercadopago_signature',['ip'=>Request::ip()]);throw new RuntimeException('Assinatura do webhook inválida.');}}
    private function syncSubscription(string $providerId):void{$d=HttpClient::get('https://api.mercadopago.com/preapproval/'.rawurlencode($providerId),$this->headers());$ref=(string)($d['external_reference']??'');$status=match($d['status']??''){ 'authorized'=>'active','paused'=>'paused','cancelled','canceled'=>'cancelled',default=>'pending'};$pdo=Database::get();$s=$pdo->prepare('SELECT id,user_id,plan_id FROM subscriptions WHERE provider_subscription_id=? OR external_reference=? LIMIT 1');$s->execute([$providerId,$ref]);$sub=$s->fetch();if(!$sub)return;$pdo->prepare('UPDATE subscriptions SET provider_subscription_id=?,status=?,starts_at=COALESCE(starts_at,NOW()),current_period_start=COALESCE(current_period_start,NOW()),updated_at=NOW() WHERE id=?')->execute([$providerId,$status,$sub['id']]);}
    private function syncPayment(string $paymentId):void{$d=HttpClient::get('https://api.mercadopago.com/v1/payments/'.rawurlencode($paymentId),$this->headers());$ref=(string)($d['external_reference']??'');$pdo=Database::get();$s=$pdo->prepare('SELECT s.*,p.credits,p.duration_days,p.price FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.external_reference=? OR s.provider_subscription_id=? LIMIT 1');$preapproval=(string)($d['metadata']['preapproval_id']??$d['preapproval_id']??'');$s->execute([$ref,$preapproval]);$sub=$s->fetch();if(!$sub)return;$status=(string)($d['status']??'unknown');$amount=(float)($d['transaction_amount']??$sub['price']);$paidAt=!empty($d['date_approved'])?date('Y-m-d H:i:s',strtotime($d['date_approved'])):null;$pdo->beginTransaction();try{$ins=$pdo->prepare("INSERT INTO payments(user_id,subscription_id,plan_id,provider,external_reference,provider_payment_id,status,amount,currency,paid_at,raw_payload,created_at,updated_at) VALUES(?,?,?,'mercadopago',?,?,?,?, 'BRL',?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE status=VALUES(status),paid_at=VALUES(paid_at),raw_payload=VALUES(raw_payload),updated_at=NOW()");$ins->execute([$sub['user_id'],$sub['id'],$sub['plan_id'],$ref,$paymentId,$status,$amount,$paidAt,json_encode($d,JSON_UNESCAPED_UNICODE)]);$pay=$pdo->prepare('SELECT id,status FROM payments WHERE provider_payment_id=?');$pay->execute([$paymentId]);$payment=$pay->fetch();if($status==='approved'){$tx=$pdo->prepare("SELECT id FROM credit_transactions WHERE reference_type='payment' AND reference_id=? LIMIT 1");$tx->execute([$paymentId]);if(!$tx->fetch()){$bal=$pdo->prepare('SELECT balance FROM user_credits WHERE user_id=? FOR UPDATE');$bal->execute([$sub['user_id']]);$oldBalance=(int)$bal->fetchColumn();if($oldBalance>0){$pdo->prepare("INSERT INTO credit_transactions(user_id,type,amount,balance_after,description,reference_type,reference_id,status,created_at) VALUES(?,'expiration',?,0,'Expiração do ciclo anterior','subscription_cycle',?,'confirmed',NOW())")->execute([$sub['user_id'],$oldBalance,$paymentId]);}$new=(int)$sub['credits'];$pdo->prepare('UPDATE user_credits SET balance=?,updated_at=NOW() WHERE user_id=?')->execute([$new,$sub['user_id']]);$pdo->prepare("INSERT INTO credit_transactions(user_id,type,amount,balance_after,description,reference_type,reference_id,status,created_at) VALUES(?,'credit',?,?,'Créditos do novo ciclo da assinatura','payment',?,'confirmed',NOW())")->execute([$sub['user_id'],$sub['credits'],$new,$paymentId]);}$pdo->prepare("UPDATE subscriptions SET status='active',current_period_start=NOW(),current_period_end=DATE_ADD(NOW(),INTERVAL ? DAY),last_credits_granted_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$sub['duration_days'],$sub['id']]);}$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
    private function syncAuthorizedPayment(string $authorizedId):void{$d=HttpClient::get('https://api.mercadopago.com/authorized_payments/'.rawurlencode($authorizedId),$this->headers());$paymentId=$d['payment']['id']??$d['payment_id']??null;if($paymentId)$this->syncPayment((string)$paymentId);}
    private function markEvent(string $key,string $status,?string $error=null):void{Database::get()->prepare('UPDATE webhook_events SET status=?,error_message=?,processed_at=NOW() WHERE event_key=?')->execute([$status,$error?mb_substr($error,0,500):null,$key]);}
}
